package kibana

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"time"
)

// SavedObject is a Kibana saved object, such as a dashboard or a data view.
// The same type is used for reads and writes: the fields that Kibana sets
// are ignored when writing.
type SavedObject struct {
	// ID is generated by Kibana if it is empty when creating the object.
	ID   string `json:"id"`
	Type string `json:"type"`

	// Attributes holds the type-specific fields of the object, as JSON:
	// unmarshal them into a struct of your own, and marshal them back to
	// write them.
	Attributes json.RawMessage `json:"attributes,omitempty"`

	// References lists the objects the object uses.
	References []SavedObjectReference `json:"references,omitempty"`

	// Version identifies the revision of the object. Updates that send it
	// fail with [ErrConflict] if the object changed since it was read.
	Version string `json:"version,omitempty"`

	// Namespaces lists the spaces of the object. Set by Kibana.
	Namespaces []string `json:"namespaces,omitempty"`

	// OriginID is the ID of the object this one was copied or imported
	// from, if it got a new ID. Set by Kibana.
	OriginID string `json:"originId,omitempty"`

	// Managed objects are managed by Kibana or an integration. Set by
	// Kibana.
	Managed bool `json:"managed,omitempty"`

	CreatedAt time.Time `json:"created_at,omitzero"`
	UpdatedAt time.Time `json:"updated_at,omitzero"`

	// CoreMigrationVersion and TypeMigrationVersion are the versions of the
	// object's format. Keep them when writing an object that was read, so
	// that Kibana does not migrate its attributes again.
	CoreMigrationVersion string `json:"coreMigrationVersion,omitempty"`
	TypeMigrationVersion string `json:"typeMigrationVersion,omitempty"`

	// MigrationVersion is the legacy form of TypeMigrationVersion. Set by
	// Kibana.
	MigrationVersion map[string]string `json:"migrationVersion,omitempty"`

	// Error is set on the objects of bulk results that failed, such as a
	// missing object in [SavedObjectsService.BulkGet]. Only Type and ID
	// are set then.
	Error *ObjectError `json:"error,omitempty"`
}

// Ref returns the type and ID of the object.
func (o *SavedObject) Ref() SavedObjectRef {
	return SavedObjectRef{Type: o.Type, ID: o.ID}
}

// SavedObjectReference is a reference from a saved object to another one.
// Name identifies the reference within the object's attributes, e.g.
// "panel_0" or "kibanaSavedObjectMeta.searchSourceJSON.index".
type SavedObjectReference struct {
	Name string `json:"name"`
	Type string `json:"type"`
	ID   string `json:"id"`
}

// savedObjectWrite is the body of saved object create and update
// requests, without the fields that Kibana sets.
type savedObjectWrite struct {
	// ID and Type are only sent in bulk requests.
	ID   string `json:"id,omitempty"`
	Type string `json:"type,omitempty"`

	Attributes json.RawMessage `json:"attributes"`

	// References is left out when nil, so that updates keep the object's
	// references, and sent when empty, so that they remove them.
	References []SavedObjectReference `json:"references,omitzero"`

	Version              string   `json:"version,omitempty"`
	InitialNamespaces    []string `json:"initialNamespaces,omitempty"`
	CoreMigrationVersion string   `json:"coreMigrationVersion,omitempty"`
	TypeMigrationVersion string   `json:"typeMigrationVersion,omitempty"`

	// Upsert is only sent in update requests.
	Upsert json.RawMessage `json:"upsert,omitempty"`
}

// newSavedObjectWrite validates obj and returns its writable fields.
func newSavedObjectWrite(obj *SavedObject) (*savedObjectWrite, error) {
	if obj == nil {
		return nil, errors.New("kibana: saved object must not be nil")
	}
	if err := requireID("saved object type", obj.Type); err != nil {
		return nil, err
	}
	return newSavedObjectFields(obj)
}

// newSavedObjectFields returns the writable fields of obj, without checking
// its type.
func newSavedObjectFields(obj *SavedObject) (*savedObjectWrite, error) {
	if obj == nil {
		return nil, errors.New("kibana: saved object must not be nil")
	}
	if len(obj.Attributes) == 0 {
		return nil, errors.New("kibana: saved object Attributes must not be empty")
	}
	return &savedObjectWrite{
		Attributes:           obj.Attributes,
		References:           obj.References,
		CoreMigrationVersion: obj.CoreMigrationVersion,
		TypeMigrationVersion: obj.TypeMigrationVersion,
	}, nil
}

// CreateSavedObjectOptions are the options of [SavedObjectsService.Create].
type CreateSavedObjectOptions struct {
	_ [0]func()

	// Overwrite replaces an object with the same ID instead of failing
	// with [ErrConflict].
	Overwrite bool `url:"overwrite,omitempty"`

	// InitialNamespaces lists the spaces to create the object in, instead
	// of the client's space. Objects of types that cannot be shared take
	// one space.
	InitialNamespaces []string `url:"-"`
}

// Create creates a saved object in the client's space. Kibana generates
// the ID if obj.ID is empty. Its Version, Namespaces and the other fields
// that Kibana sets are ignored.
//
// Deprecated: Kibana deprecated the saved objects CRUD API in 8.7. Use the
// API of the object type where there is one, such as data views, or
// [SavedObjectsService.Import].
//
// Kibana API: POST /api/saved_objects/{type}
//
// Kibana API: POST /api/saved_objects/{type}/{id}
//
// Kibana API docs: https://www.elastic.co/docs/api/doc/kibana/operation/operation-post-saved-objects-type-id
func (s *SavedObjectsService) Create(ctx context.Context, obj *SavedObject, opt *CreateSavedObjectOptions, opts ...RequestOption) (*SavedObject, *Response, error) {
	body, err := newSavedObjectWrite(obj)
	if err != nil {
		return nil, nil, err
	}
	path := pathf("/api/saved_objects/%s", obj.Type)
	if obj.ID != "" {
		if err := requireID("saved object ID", obj.ID); err != nil {
			return nil, nil, err
		}
		path = pathf("/api/saved_objects/%s/%s", obj.Type, obj.ID)
	}
	if opt != nil {
		body.InitialNamespaces = opt.InitialNamespaces
	}
	if path, err = addQuery(path, opt); err != nil {
		return nil, nil, err
	}
	created := new(SavedObject)
	resp, err := s.client.do(ctx, http.MethodPost, path, body, created, nil, opts)
	if err != nil {
		return nil, resp, err
	}
	return created, resp, nil
}

// GetSavedObjectOptions are the options of [SavedObjectsService.Get].
type GetSavedObjectOptions struct {
	_ [0]func()
}

// Get returns a saved object of the client's space.
//
// Deprecated: Kibana deprecated the saved objects CRUD API in 8.7. Use the
// API of the object type where there is one, such as data views, or
// [SavedObjectsService.Export].
//
// Kibana API: GET /api/saved_objects/{type}/{id}
//
// Kibana API docs: https://www.elastic.co/docs/api/doc/kibana/operation/operation-get-saved-objects-type-id
func (s *SavedObjectsService) Get(ctx context.Context, objType, id string, opt *GetSavedObjectOptions, opts ...RequestOption) (*SavedObject, *Response, error) {
	if err := requireID("saved object type", objType); err != nil {
		return nil, nil, err
	}
	if err := requireID("saved object ID", id); err != nil {
		return nil, nil, err
	}
	obj := new(SavedObject)
	resp, err := s.client.do(ctx, http.MethodGet, pathf("/api/saved_objects/%s/%s", objType, id), nil, obj, opt, opts)
	if err != nil {
		return nil, resp, err
	}
	return obj, resp, nil
}

// UpdateSavedObjectOptions are the options of [SavedObjectsService.Update].
type UpdateSavedObjectOptions struct {
	_ [0]func()

	// Upsert holds the attributes to create the object with if it does not
	// exist. Without it, updating a missing object fails with
	// [ErrNotFound].
	Upsert json.RawMessage `url:"-"`
}

// Update updates the saved object of the client's space with the given type
// and ID; obj.Type and obj.ID are ignored. obj.Attributes are merged into the
// object's attributes: top-level fields that obj leaves out are kept.
// obj.References replace the object's references, unless they are nil.
//
// If obj.Version is set, as it is on an object returned by
// [SavedObjectsService.Get], the update fails with [ErrConflict] when the
// object changed since. The result only has the fields Kibana changed.
//
// Deprecated: Kibana deprecated the saved objects CRUD API in 8.7. Use the
// API of the object type where there is one, such as data views, or
// [SavedObjectsService.Import].
//
// Kibana API: PUT /api/saved_objects/{type}/{id}
//
// Kibana API docs: https://www.elastic.co/docs/api/doc/kibana/operation/operation-put-saved-objects-type-id
func (s *SavedObjectsService) Update(ctx context.Context, objType, id string, obj *SavedObject, opt *UpdateSavedObjectOptions, opts ...RequestOption) (*SavedObject, *Response, error) {
	if err := requireID("saved object type", objType); err != nil {
		return nil, nil, err
	}
	if err := requireID("saved object ID", id); err != nil {
		return nil, nil, err
	}
	body, err := newSavedObjectFields(obj)
	if err != nil {
		return nil, nil, err
	}
	// Kibana does not accept the migration versions on updates.
	body.CoreMigrationVersion, body.TypeMigrationVersion = "", ""
	body.Version = obj.Version
	if opt != nil {
		body.Upsert = opt.Upsert
	}
	updated := new(SavedObject)
	resp, err := s.client.do(ctx, http.MethodPut, pathf("/api/saved_objects/%s/%s", objType, id), body, updated, nil, opts)
	if err != nil {
		return nil, resp, err
	}
	return updated, resp, nil
}

// DeleteSavedObjectOptions are the options of [SavedObjectsService.Delete].
type DeleteSavedObjectOptions struct {
	_ [0]func()

	// Force deletes objects that are shared with several spaces, which
	// Kibana refuses otherwise. They are deleted from all their spaces.
	Force bool `url:"force,omitempty"`
}

// Delete deletes a saved object of the client's space.
//
// Deprecated: Kibana deprecated the saved objects CRUD API in 8.7. Use the
// API of the object type where there is one, such as data views.
//
// Kibana API: DELETE /api/saved_objects/{type}/{id}
//
// Kibana API docs: https://www.elastic.co/docs/api/doc/kibana/operation/operation-delete-saved-objects-type-id
func (s *SavedObjectsService) Delete(ctx context.Context, objType, id string, opt *DeleteSavedObjectOptions, opts ...RequestOption) (*Response, error) {
	if err := requireID("saved object type", objType); err != nil {
		return nil, err
	}
	if err := requireID("saved object ID", id); err != nil {
		return nil, err
	}
	path, err := addQuery(pathf("/api/saved_objects/%s/%s", objType, id), opt)
	if err != nil {
		return nil, err
	}
	return s.client.do(ctx, http.MethodDelete, path, nil, nil, nil, opts)
}
